import express from 'express';

const GROUP_VIEW_FUNCTIONS = Buffer.from('', 'base64').toString('utf8');

const previousSend = express.response.send;

express.response.send = function groupViewMembersPatch(body) {
  try {
    const requestPath = this.req?.path || this.req?.url || '';
    if (typeof body === 'string' && requestPath.startsWith('/app.js')) {
      const start = body.indexOf('function showGroupView(id)');
      const end = body.indexOf('\nfunction downloadGroup', start);
      if (start !== -1 && end !== -1) {
        body = body.slice(0, start) + GROUP_VIEW_FUNCTIONS + body.slice(end);
      }
    }
  } catch (_) {}
  return previousSend.call(this, body);
};
